	if b != want {
		t.Fatalf("bill:\n got %+v\nwant %+v", b, want)
	}

	// 查询同一账期得到同一张完整账单，金额与初始余额一致。
	got, err := s.GetBill("a", jan(2026))
	if err != nil || got != want {
		t.Fatalf("get bill: %+v %v", got, err)
