package meter

import (
	"errors"
	"testing"
	"time"
)

func may(y int) Month { return Month{Year: y, Month: time.May} }

// TestHistoricalBillsKeepLockedTermsAcrossChangeCancelResubscribe 是历史账单
// 计价的端到端回归：同一账户先安排换套餐（锁定目标套餐当时的完整条件）、
// 按月取消、空档一个月后按修改过的套餐重新开通，再先出新月账单、后补开旧月
// 账单。旧账期必须使用那段订阅当时锁定的条件快照，既不能被后来的订阅覆盖，
// 也不能被同一套餐的新价格覆盖。
//
// 时间线（全部 UTC）：
//
//	2026-01-01 开通套餐甲：月费 1000、额度 10、超额单价 100、税率 10%。
//	2026-01-15 安排 2 月起换套餐乙，安排时乙：月费 2000、额度 20、
//	           超额单价 200、税率 10%；安排锁定该完整快照。
//	之后       把乙的当前定义改为：月费 4000、额度 1、超额单价 500、税率 20%。
//	1 月用量 12、2 月用量 25，均在当时接收，两月均未出账。
//	2026-02-15 登记按月取消，2026-03-01 00:00 终止；3 月整月无订阅。
//	2026-04-01 按修改后的乙重新开通；4 月无用量。
//	2026-05-01 先出 4 月账单，再尝试 3 月，最后补开 2 月、1 月账单。
func TestHistoricalBillsKeepLockedTermsAcrossChangeCancelResubscribe(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 1, 0, 0))

	jia := Plan{ID: "jia", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000}
	yiOld := Plan{ID: "yi", MonthlyFee: 2000, IncludedUnits: 20, OveragePrice: 200, TaxRateBasisPoints: 1000}
	yiNew := Plan{ID: "yi", MonthlyFee: 4000, IncludedUnits: 1, OveragePrice: 500, TaxRateBasisPoints: 2000}
	jiaTerms := termsOf(jia)
	yiOldTerms := termsOf(yiOld)
	yiNewTerms := termsOf(yiNew)

	mustPlan(t, s, jia)
	mustPlan(t, s, yiOld)
	mustAccount(t, s, "u")
	mustSubscribe(t, s, "u", "jia", utc(2026, 1, 1, 0, 0))

	// 1 月中旬安排 2 月起改用乙：安排成功时锁定乙的完整条件与生效账期。
	clk.t = utc(2026, 1, 15, 12, 0)
	change := mustSchedule(t, s, "u", "yi")
	if !change.Created || change.Change.TargetPlanID != "yi" ||
		change.Change.EffectivePeriod != feb(2026) || change.Change.Terms != yiOldTerms {
		t.Fatalf("scheduled change = %+v, want locked old yi terms effective Feb", change)
	}

	// 安排成功后修改乙的当前定义：待生效安排仍持锁，不重新取价。
	if err := s.UpdatePlan(yiNew); err != nil {
		t.Fatalf("update yi: %v", err)
	}
	st, _ := s.Status("u")
	if st.PendingChange == nil || st.PendingChange.Terms != yiOldTerms {
		t.Fatalf("pending change re-priced by plan update: %+v", st.PendingChange)
	}
	// 同一目标套餐的重复安排返回原安排、不重新取价。
	replay, err := s.SchedulePlanChange("u", "yi")
	if err != nil || replay.Created || replay.Change.Terms != yiOldTerms {
		t.Fatalf("repeat schedule re-priced: %+v %v", replay, err)
	}

	// 1 月接收 12 单位。
	clk.t = utc(2026, 1, 20, 12, 0)
	if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-jan", At: utc(2026, 1, 20, 0, 0), Quantity: 12}); err != nil ||
		!r.Accepted || r.Period != jan(2026) {
		t.Fatalf("jan usage: %+v %v", r, err)
	}

	// 2/1 零点切换自动生效，无需任何操作；当前条件是锁定的旧乙，而非新定义。
	clk.t = utc(2026, 2, 10, 12, 0)
	st, _ = s.Status("u")
	if !st.Subscribed || st.CurrentTerms != yiOldTerms || st.PendingChange != nil {
		t.Fatalf("feb current terms = %+v pending = %+v, want locked old yi", st.CurrentTerms, st.PendingChange)
	}
	// 2 月接收 25 单位。
	if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-feb", At: utc(2026, 2, 10, 0, 0), Quantity: 25}); err != nil ||
		!r.Accepted || r.Period != feb(2026) {
		t.Fatalf("feb usage: %+v %v", r, err)
	}

	// 2 月中旬登记按月取消：终止时刻为 3/1 零点，2 月仍按完整月费与额度计费。
	clk.t = utc(2026, 2, 15, 12, 0)
	cancelRes := mustCancel(t, s, "u")
	if !cancelRes.Cancelled || !cancelRes.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
		t.Fatalf("cancel result = %+v, want end 2026-03-01", cancelRes)
	}

	// 3/1 终止：无有效订阅、无当前套餐；3 月整月空档，事件被拒。
	clk.t = utc(2026, 3, 10, 12, 0)
	st, _ = s.Status("u")
	if st.Subscribed || st.CurrentTerms != (PlanTerms{}) || st.ScheduledEnd != nil {
		t.Fatalf("status during gap: %+v", st)
	}
	if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-mar", At: utc(2026, 3, 5, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
		t.Fatalf("march event in gap: %v", err)
	}

	// 4/1 按修改后的乙重新开通：当前条件采用新定义；历史用量继续保留。
	clk.t = utc(2026, 4, 1, 0, 0)
	mustSubscribe(t, s, "u", "yi", utc(2026, 4, 1, 0, 0))
	st, _ = s.Status("u")
	if !st.Subscribed || st.CurrentTerms != yiNewTerms {
		t.Fatalf("current terms after resubscribe = %+v, want updated yi", st.CurrentTerms)
	}
	if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 12 {
		t.Fatalf("jan usage after resubscribe = %d, want 12", u.Total)
	}
	if u, _ := s.MonthlyUsage("u", feb(2026)); u.Total != 25 {
		t.Fatalf("feb usage after resubscribe = %d, want 25", u.Total)
	}

	// 5 月：先为重新开通后的 4 月出账——零用量，按新乙：
	// 月费 4000、税 20% = 800、应付 4800。
	clk.t = utc(2026, 5, 1, 0, 0)
	aprBill, err := s.CreateBill("u", apr(2026))
	if err != nil {
		t.Fatalf("create apr bill: %v", err)
	}
	wantHistoricalBill(t, aprBill, apr(2026), yiNewTerms,
		0, // total usage
		4000, 0, 800, 4800)

	// 重新开通不能把无订阅的 3 月变成可出账月份：出账仍返回账期未被订阅
	// 覆盖的现有错误，且查询不到该月账单。
	if _, err := s.CreateBill("u", mar(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
		t.Fatalf("create march gap bill: %v", err)
	}
	if _, err := s.GetBill("u", mar(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("march bill queryable after failed create: %v", err)
	}

	// 补开 2 月账单：必须保持安排换套餐时锁定的旧乙条件，
	// 月费 2000、额度 20、超额 (25-20)*200 = 1000、税 3000*10% = 300、应付 3300。
	febBill, err := s.CreateBill("u", feb(2026))
	if err != nil {
		t.Fatalf("backfill feb bill: %v", err)
	}
	wantHistoricalBill(t, febBill, feb(2026), yiOldTerms,
		25, // total usage
		2000, 1000, 300, 3300)

	// 再补开 1 月账单：仍按甲条件，
	// 月费 1000、额度 10、超额 (12-10)*100 = 200、税 1200*10% = 120、应付 1320。
	janBill, err := s.CreateBill("u", jan(2026))
	if err != nil {
		t.Fatalf("backfill jan bill: %v", err)
	}
	wantHistoricalBill(t, janBill, jan(2026), jiaTerms,
		12, // total usage
		1000, 200, 120, 1320)

	// 已成功生成的历史账单，随后查询得到完全相同的计费条件、金额与用量；
	// 重复出账返回同一张账单。
	for _, original := range []Bill{aprBill, febBill, janBill} {
		got, err := s.GetBill("u", original.Period)
		if err != nil {
			t.Fatalf("get bill %s: %v", original.Period, err)
		}
		if got != original {
			t.Fatalf("bill %s changed between create and get:\ncreate=%+v\nget   =%+v", original.Period, original, got)
		}
		again, err := s.CreateBill("u", original.Period)
		if err != nil {
			t.Fatalf("recreate bill %s: %v", original.Period, err)
		}
		if again != original {
			t.Fatalf("bill %s not idempotent:\nfirst =%+v\nagain=%+v", original.Period, original, again)
		}
	}

	// 各月用量查询与账单展示的用量明细分别对应历史月份。
	for _, w := range []struct {
		period         Month
		total, overage int64
		included       int64
	}{
		{jan(2026), 12, 2, 10},
		{feb(2026), 25, 5, 20},
		{apr(2026), 0, 0, 1},
	} {
		if u, _ := s.MonthlyUsage("u", w.period); u.Total != w.total {
			t.Fatalf("usage %s = %d, want %d", w.period, u.Total, w.total)
		}
		b, _ := s.GetBill("u", w.period)
		if b.TotalUsage != w.total || b.OverageUnits != w.overage || b.IncludedUnits != w.included {
			t.Fatalf("bill %s usage detail = total %d over %d included %d, want total %d over %d included %d",
				w.period, b.TotalUsage, b.OverageUnits, b.IncludedUnits, w.total, w.overage, w.included)
		}
	}
	// 空档 3 月用量查询为零且没有账单。
	if u, _ := s.MonthlyUsage("u", mar(2026)); u.Total != 0 {
		t.Fatalf("march usage = %d, want 0", u.Total)
	}

	// 补开旧账单后，账户当前套餐仍是重新开通时采用的新乙条件；
	// 账单按账期排列且只包含 1、2、4 月（3 月空档不在其中）。
	st, _ = s.Status("u")
	if !st.Subscribed || st.CurrentTerms != yiNewTerms {
		t.Fatalf("current terms after backfill = %+v, want updated yi", st.CurrentTerms)
	}
	wantSummaries := []struct {
		period Month
		due    int64
	}{
		{jan(2026), 1320},
		{feb(2026), 3300},
		{apr(2026), 4800},
	}
	if len(st.Bills) != len(wantSummaries) {
		t.Fatalf("status bills = %+v, want %d", st.Bills, len(wantSummaries))
	}
	for i, w := range wantSummaries {
		got := st.Bills[i]
		if got.Period != w.period || got.TotalDue != w.due || got.Paid != 0 ||
			got.Balance != w.due || got.Settled {
			t.Fatalf("status bills[%d] = %+v, want period %s due %d unpaid", i, got, w.period, w.due)
		}
		if !got.DueAt.Equal(w.period.End().AddDate(0, 0, 7)) {
			t.Fatalf("status bills[%d] due at = %v", i, got.DueAt)
		}
	}
}

// wantHistoricalBill 断言一张历史账单展示的套餐条件、包含额度、用量明细与
// 全部金额字段；尚未登记付款时已付为零、余额等于应付、未付清。
func wantHistoricalBill(t *testing.T, b Bill, period Month, wantTerms PlanTerms,
	totalUsage, monthlyFee, overageFee, tax, totalDue int64) {
	t.Helper()
	if b.AccountID != "u" || b.Period != period {
		t.Fatalf("bill identity = %s/%s, want u/%s", b.AccountID, b.Period, period)
	}
	// 套餐条件必须是该账期当时锁定的完整快照，而不只是总额碰巧正确。
	if b.Terms != wantTerms {
		t.Fatalf("bill %s terms = %+v, want %+v", period, b.Terms, wantTerms)
	}
	wantOverage := totalUsage - wantTerms.IncludedUnits
	if wantOverage < 0 {
		wantOverage = 0
	}
	if b.TotalUsage != totalUsage || b.IncludedUnits != wantTerms.IncludedUnits || b.OverageUnits != wantOverage {
		t.Fatalf("bill %s usage detail = total %d included %d overage %d, want total %d included %d overage %d",
			period, b.TotalUsage, b.IncludedUnits, b.OverageUnits,
			totalUsage, wantTerms.IncludedUnits, wantOverage)
	}
	if b.MonthlyFee != monthlyFee || b.OverageFee != overageFee || b.Tax != tax || b.TotalDue != totalDue {
		t.Fatalf("bill %s amounts = fee %d overageFee %d tax %d due %d, want %d %d %d %d",
			period, b.MonthlyFee, b.OverageFee, b.Tax, b.TotalDue,
			monthlyFee, overageFee, tax, totalDue)
	}
	// 尚未登记付款：已付为零、余额等于应付。
	if b.Paid != 0 || b.Balance != totalDue || b.Settled {
		t.Fatalf("bill %s payment state = paid %d balance %d settled %v, want 0/%d/false",
			period, b.Paid, b.Balance, b.Settled, totalDue)
	}
	if !b.DueAt.Equal(period.End().AddDate(0, 0, 7)) {
		t.Fatalf("bill %s due at = %v, want %s+7d", period, b.DueAt, period.End())
	}
}

package meter

import (
	"errors"
	"sync"
	"testing"
	"time"
)

// 本文件回归“迟到用量与月度出账同时发生”的账期边界：
//
//	账户于 2026-01-01 00:00:00 UTC 开通，套餐月费 1000 分、包含 10 单位、
//	超额单价 7 分、税率万分之 500（5%）。一月已接收用量 8 单位且尚未出账。
//	当前时刻为 2026-02-01 00:00:00 UTC：一月已经结束，此时用户一边补报
//	一条发生在 2026-01-31 23:59:59 UTC、数量 5 单位的新事件（事件应归入
//	一月），一边为一月生成账单。
//
// 两种先后顺序都符合现有规则，测试不规定并发时必须哪项先成功，但要求
// 事件结果、累计用量与账单始终对应同一个确定结果：
//
//   - 事件先被接收：Accepted=true，一月累计 13，账单总用量 13、超额 3、
//     超额费用 21、税额 51、应付 1072。
//   - 账单先生成：事件返回现有 ErrMonthBilled，一月累计保持 8，账单总用量
//     8、无超额、税额 50、应付 1050。
//
// 既不能“用量已接收却未计费”，也不能“上报失败却增加了账单金额”。

var boundaryTerms = PlanTerms{
	PlanID:             "boundary-plan",
	MonthlyFee:         1000,
	IncludedUnits:      10,
	OveragePrice:       7,
	TaxRateBasisPoints: 500,
}

// newLateUsageScenario 搭建共同的初始状态：时钟停在 2026-02-01 00:00:00 UTC，
// 一月已接收 8 单位用量、尚未出账，账户无其他账单与欠费。
func newLateUsageScenario(t *testing.T) *Service {
	t.Helper()
	s, clk := newTestService(utc(2026, 1, 20, 12, 0))
	mustPlan(t, s, Plan{
		ID:                 boundaryTerms.PlanID,
		MonthlyFee:         boundaryTerms.MonthlyFee,
		IncludedUnits:      boundaryTerms.IncludedUnits,
		OveragePrice:       boundaryTerms.OveragePrice,
		TaxRateBasisPoints: boundaryTerms.TaxRateBasisPoints,
	})
	mustAccount(t, s, "u")
	mustSubscribe(t, s, "u", boundaryTerms.PlanID, utc(2026, 1, 1, 0, 0))
	if r, err := s.RecordEvent(Event{
		AccountID: "u",
		EventID:   "jan-usage-8",
		At:        utc(2026, 1, 20, 0, 0),
		Quantity:  8,
	}); err != nil || !r.Accepted || r.Period != jan(2026) {
		t.Fatalf("seed january usage: %+v %v", r, err)
	}
	// 进入二月零点：一月已结束，补报事件与出账都在此时发起。
	clk.t = utc(2026, 2, 1, 0, 0)
	return s
}

// lateJanuaryEvent 是一月末发生、二月补报的新事件：账户此前未接收过该标识。
func lateJanuaryEvent() Event {
	return Event{
		AccountID: "u",
		EventID:   "late-jan-31-5",
		At:        time.Date(2026, time.January, 31, 23, 59, 59, 0, time.UTC),
		Quantity:  5,
	}
}

// wantJanuaryBoundaryBill 按“事件先接收 / 账单先生成”两种结果之一断言
// 一月账单的完整金额、用量与付款状态。
func wantJanuaryBoundaryBill(t *testing.T, b Bill, accepted bool) {
	t.Helper()
	want := struct {
		totalUsage, overageUnits, overageFee, tax, due int64
	}{8, 0, 0, 50, 1050}
	if accepted {
		// (1000 + 3*7) = 1021；1021*5% = 51.05 → 四舍五入 51；应付 1072。
		want = struct {
			totalUsage, overageUnits, overageFee, tax, due int64
		}{13, 3, 21, 51, 1072}
	}
	if b.AccountID != "u" || b.Period != jan(2026) {
		t.Fatalf("bill identity = %s/%s, want u/2026-01", b.AccountID, b.Period)
	}
	if b.Terms != boundaryTerms || b.IncludedUnits != boundaryTerms.IncludedUnits {
		t.Fatalf("bill terms = %+v included=%d, want snapshot %+v", b.Terms, b.IncludedUnits, boundaryTerms)
	}
	if b.TotalUsage != want.totalUsage || b.OverageUnits != want.overageUnits ||
		b.OverageFee != want.overageFee || b.MonthlyFee != 1000 ||
		b.Tax != want.tax || b.TotalDue != want.due {
		t.Fatalf("accepted=%v bill amounts/usage = usage %d overUnits %d fee %d overFee %d tax %d due %d, "+
			"want usage %d overUnits %d fee 1000 overFee %d tax %d due %d",
			accepted,
			b.TotalUsage, b.OverageUnits, b.MonthlyFee, b.OverageFee, b.Tax, b.TotalDue,
			want.totalUsage, want.overageUnits, want.overageFee, want.tax, want.due)
	}
	if b.Paid != 0 || b.Balance != want.due || b.Settled {
		t.Fatalf("bill payment state = paid %d balance %d settled %v, want 0/%d/false",
			b.Paid, b.Balance, b.Settled, want.due)
	}
	if !b.DueAt.Equal(utc(2026, 2, 8, 0, 0)) {
		t.Fatalf("due at = %v, want 2026-02-08", b.DueAt)
	}
}

// assertJanuaryBoundaryState 断言查询用量、查询账单与账户状态展示相符数据，
// 并校验一月账单的幂等再出账沿用既有金额与用量。
func assertJanuaryBoundaryState(t *testing.T, s *Service, accepted bool) {
	t.Helper()
	wantUsage := int64(8)
	if accepted {
		wantUsage = 13
	}
	if u, err := s.MonthlyUsage("u", jan(2026)); err != nil || u.Total != wantUsage {
		t.Fatalf("january usage = %d (%v), want %d", u.Total, err, wantUsage)
	}
	got, err := s.GetBill("u", jan(2026))
	if err != nil {
		t.Fatalf("get january bill: %v", err)
	}
	wantJanuaryBoundaryBill(t, got, accepted)

	// 再次为一月出账：沿用已经生成的金额与用量，返回同一张账单。
	again, err := s.CreateBill("u", jan(2026))
	if err != nil || again != got {
		t.Fatalf("re-bill january not identical: %+v vs %+v err=%v", again, got, err)
	}

	st, err := s.Status("u")
	if err != nil {
		t.Fatalf("status: %v", err)
	}
	// 订阅不受出账影响；二月零点距一月账单截止（2/8）尚早，不停用。
	if !st.Subscribed || st.Suspended || st.CurrentTerms != boundaryTerms {
		t.Fatalf("account status = sub %v suspended %v terms %+v, want subscribed/not suspended/boundary terms",
			st.Subscribed, st.Suspended, st.CurrentTerms)
	}
	if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0].Period != jan(2026) ||
		st.MonthlyUsage[0].Total != wantUsage {
		t.Fatalf("status monthly usage = %+v, want january %d", st.MonthlyUsage, wantUsage)
	}
	if len(st.Bills) != 1 {
		t.Fatalf("status bills = %+v, want exactly one january bill", st.Bills)
	}
	sum := st.Bills[0]
	wantDue := int64(1050)
	if accepted {
		wantDue = 1072
	}
	if sum.Period != jan(2026) || sum.TotalDue != wantDue || sum.Paid != 0 ||
		sum.Balance != wantDue || sum.Settled {
		t.Fatalf("status bill summary = %+v, want january due %d unpaid", sum, wantDue)
	}
	if !sum.DueAt.Equal(utc(2026, 2, 8, 0, 0)) {
		t.Fatalf("status bill due at = %v, want 2026-02-08", sum.DueAt)
	}
}

// TestLateUsageAcceptedBeforeJanuaryBill：补报事件先被接收，随后一月出账。
// 事件按发生时刻归入一月：本次新增成功，一月累计与账单总用量都为 13。
func TestLateUsageAcceptedBeforeJanuaryBill(t *testing.T) {
	s := newLateUsageScenario(t)
	ev := lateJanuaryEvent()

	r, err := s.RecordEvent(ev)
	if err != nil || !r.Accepted || r.Period != jan(2026) {
		t.Fatalf("late event before bill = %+v %v, want accepted into january", r, err)
	}

	b, err := s.CreateBill("u", jan(2026))
	if err != nil {
		t.Fatalf("create january bill: %v", err)
	}
	wantJanuaryBoundaryBill(t, b, true)
	assertJanuaryBoundaryState(t, s, true)

	// 已接收事件在出账后原样重报：仍成功，但表示没有再次累计。
	replay, err := s.RecordEvent(ev)
	if err != nil || replay.Accepted || replay.Period != jan(2026) {
		t.Fatalf("identical replay after billed = %+v %v, want success not re-accumulated", replay, err)
	}
	assertJanuaryBoundaryState(t, s, true)
}

// TestJanuaryBillCreatedBeforeLateUsage：一月账单先生成，补报事件随后被拒。
// 返回现有的已出账错误，用量与账单金额均保持为出账时的确定结果。
func TestJanuaryBillCreatedBeforeLateUsage(t *testing.T) {
	s := newLateUsageScenario(t)
	ev := lateJanuaryEvent()

	b, err := s.CreateBill("u", jan(2026))
	if err != nil {
		t.Fatalf("create january bill: %v", err)
	}
	wantJanuaryBoundaryBill(t, b, false)

	if _, err := s.RecordEvent(ev); !errors.Is(err, ErrMonthBilled) {
		t.Fatalf("late event after bill = %v, want ErrMonthBilled", err)
	}
	assertJanuaryBoundaryState(t, s, false)

	// 被出账拒绝的事件原样再报仍失败：它不能变成“已接收事件的重报”
	// （重报会成功且 Accepted=false），也不得改动任何用量或金额。
	r, err := s.RecordEvent(ev)
	if !errors.Is(err, ErrMonthBilled) || r != (EventResult{}) {
		t.Fatalf("replay rejected event = %+v %v, want ErrMonthBilled with zero result", r, err)
	}
	assertJanuaryBoundaryState(t, s, false)
}

// TestLateUsageRacesJanuaryBill：两项操作经现有服务入口真正并发发起。
// 允许实际处理顺序任意，但每轮结束后世界必须恰好处于两种自洽结果之一：
// 要么“事件先成功 → 用量 13 / 账单 1072”，要么“账单先成功 → 事件被拒 /
// 用量 8 / 账单 1050”；绝不允许接收与计费互相错位。
func TestLateUsageRacesJanuaryBill(t *testing.T) {
	const iterations = 200
	var sawAccepted, sawRejected bool
	for i := 0; i < iterations; i++ {
		s := newLateUsageScenario(t)
		ev := lateJanuaryEvent()

		start := make(chan struct{})
		var wg sync.WaitGroup
		var (
			mu      sync.Mutex
			evRes   EventResult
			evErr   error
			billRes Bill
			billErr error
		)
		wg.Add(2)
		go func() {
			defer wg.Done()
			<-start
			r, err := s.RecordEvent(ev)
			mu.Lock()
			evRes, evErr = r, err
			mu.Unlock()
		}()
		go func() {
			defer wg.Done()
			<-start
			b, err := s.CreateBill("u", jan(2026))
			mu.Lock()
			billRes, billErr = b, err
			mu.Unlock()
		}()
		close(start)
		wg.Wait()

		if billErr != nil {
			t.Fatalf("iteration %d: create bill: %v", i, billErr)
		}
		switch {
		case evErr == nil && evRes.Accepted && evRes.Period == jan(2026):
			// 事件先被接收：账单必须为 13/1072，不能接收了却按 8 计费。
			sawAccepted = true
			wantJanuaryBoundaryBill(t, billRes, true)
			assertJanuaryBoundaryState(t, s, true)
			// 出账后的原样重报不再累计，账单金额不变。
			if r, err := s.RecordEvent(ev); err != nil || r.Accepted {
				t.Fatalf("iteration %d: replay accepted event = %+v %v, want dedup no-op", i, r, err)
			}
			assertJanuaryBoundaryState(t, s, true)
		case errors.Is(evErr, ErrMonthBilled) && evRes == (EventResult{}):
			// 账单先生成：事件被拒，账单必须为 8/1050，不能拒绝了却计入金额。
			sawRejected = true
			wantJanuaryBoundaryBill(t, billRes, false)
			assertJanuaryBoundaryState(t, s, false)
			// 被拒事件原样再报仍是已出账错误，不会变成成功的去重重报。
			if r, err := s.RecordEvent(ev); !errors.Is(err, ErrMonthBilled) || r != (EventResult{}) {
				t.Fatalf("iteration %d: replay rejected event = %+v %v, want ErrMonthBilled", i, r, err)
			}
			assertJanuaryBoundaryState(t, s, false)
		default:
			t.Fatalf("iteration %d: inconsistent race outcome event=%+v err=%v bill=%+v",
				i, evRes, evErr, billRes)
		}
	}
	// 并发顺序本身不可规定；两个确定性测试分别覆盖两条分支。
	// 若运行期调度恰好观察到两种顺序，记录下来便于判断本用例的实际覆盖面。
	if !sawAccepted || !sawRejected {
		t.Logf("race iterations observed accepted=%v rejected=%v; both branches are "+
			"also covered deterministically by the sequential tests", sawAccepted, sawRejected)
	}
}

