134		// 三月仍欠 1000 但截止时刻（四月八日）未到，不阻止恢复。
135		if r, err := s.RecordPayment("a", "pay-feb-2", feb(2026), 700); err != nil ||
136			!r.Registered || r.BillBalance != 0 || !r.Settled {
