142		}
143		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
144		wantBill(t, s, feb(2026), febDue, 1000, 0, true)
145		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
146	
147		// Status 的账单摘要按账期排列并反映各账期独立的付款结果。
148		if len(st.Bills) != 3 {
149			t.Fatalf("status bills = %+v", st.Bills)
150		}
151		wantSummary := []struct {
152			period        Month
153			paid, balance int64
154			settled       bool
155		}{
156			{jan(2026), 1000, 0, true},
157			{feb(2026), 1000, 0, true},
158			{mar(2026), 0, 1000, false},
159		}
160		for i, w := range wantSummary {
