169		// 且只增加这一个事件的数量（证明此前被拒不占用事件标识、不累计用量）。
170		r2, err := s.RecordEvent(aprEvent)
171		if err != nil || !r2.Accepted || r2.Period != apr(2026) {
172			t.Fatalf("apr event re-submitted after recovery: %+v %v", r2, err)
173		}
