178		if r3, err := s.RecordEvent(aprEvent); err != nil || r3.Accepted {
179			t.Fatalf("identical replay accumulates again: %+v %v", r3, err)
180		}
181		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 4 {
182			t.Fatalf("apr usage after replay = %d, want 4", u.Total)
183		}
184	
185		// 三月账单仍有余额，但四月八日零点前账户保持可接收新用量。
186		clk.t = utc(2026, 4, 7, 23, 59)
187		wantSuspended(t, s, false)
188		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr-2", At: utc(2026, 4, 7, 23, 59), Quantity: 5}); err != nil {
189			t.Fatalf("event just before mar due: %v", err)
190		}
191		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 9 {
192			t.Fatalf("apr usage = %d, want 9", u.Total)
193		}
194	
195		// 恰到三月截止时刻：无需先发生其他业务操作，Status 即显示重新停用。
196		clk.t = utc(2026, 4, 8, 0, 0)
197		st = wantSuspended(t, s, true)
198		if !st.Subscribed {
199			t.Fatalf("subscription must still be active at mar due time: %+v", st)
200		}
201		// 停用再次拒绝新增用量；被拒用量不增加累计、不占用标识（同路径规则）。
202		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr-3", At: utc(2026, 4, 8, 0, 0), Quantity: 2}); !errors.Is(err, ErrSuspended) {
203			t.Fatalf("event exactly at mar due: %v", err)
204		}
205		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 9 {
206			t.Fatalf("apr usage = %d after due rejection, want 9", u.Total)
207		}
208		// 一月、二月已结清状态不被三月到期影响。
209		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
210		wantBill(t, s, feb(2026), febDue, 1000, 0, true)
211		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
212	}
213	
214	// TestSuspensionRecoveryOrderIndependent 反向付款顺序：先全额付清二月、
215	// 再付清一月，恢复规则必须与先付一月一致——只要仍有一张到期账单有余额，
216	// 就不能因付款顺序而提前恢复；未到期的三月同样不参与判定。
217	func TestSuspensionRecoveryOrderIndependent(t *testing.T) {
218		s, _ := multiBillFixture(t)
219	
220		// 两张到期账单并存：先付清二月，一月仍到期欠费，不能恢复。
221		if r, err := s.RecordPayment("a", "pay-feb", feb(2026), 1000); err != nil ||
222			!r.Registered || r.BillBalance != 0 || !r.Settled {
223			t.Fatalf("feb paid first: %+v %v", r, err)
224		}
225		wantBill(t, s, jan(2026), utc(2026, 2, 8, 0, 0), 0, 1000, false)
226		wantBill(t, s, feb(2026), utc(2026, 3, 8, 0, 0), 1000, 0, true)
227		wantSuspended(t, s, true)
228		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr", At: utc(2026, 4, 1, 0, 0), Quantity: 4}); !errors.Is(err, ErrSuspended) {
229			t.Fatalf("event with only jan overdue: %v", err)
230		}
231	
232		// 再付清一月：到期账单全部结清，立即恢复；三月未到期不阻止。
233		if r, err := s.RecordPayment("a", "pay-jan", jan(2026), 1000); err != nil ||
234			!r.Registered || r.BillBalance != 0 || !r.Settled {
235			t.Fatalf("jan paid second: %+v %v", r, err)
236		}
237		st := wantSuspended(t, s, false)
238		if !st.Subscribed {
239			t.Fatalf("subscription must remain active: %+v", st)
240		}
241		wantBill(t, s, mar(2026), utc(2026, 4, 8, 0, 0), 0, 1000, false)
242	
243		// 恢复后四月用量可被首次接收（此前被拒不累计、不占标识）。
244		if r2, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr", At: utc(2026, 4, 1, 0, 0), Quantity: 4}); err != nil ||
245			!r2.Accepted || r2.Period != apr(2026) {
246			t.Fatalf("apr event after reverse-order recovery: %+v %v", r2, err)
247		}
248		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 4 {
249			t.Fatalf("apr usage = %d, want 4", u.Total)
250		}
251	}
